}

static void *kmalloc(unsigned size, gfp_t gfp) /* <=== kmalloc */ 
{
	void *p = memalign(64, size);
	if (!p)
		return p;

	if (gfp & __GFP_ZERO)
		memset(p, 0, size);
	return p;
}

